        "tugasUmum": [
            {
                "id": 79,
                "header": "<b>Planning, Budgeting dan Pengelolaan Anggaran</b> Mengelola, mengevaluasi, dan memastikan penyusunan dan monitoring Rencana Kerja dan Anggaran (RKA) unit kerja/fungsi dan pengelolaan anggaran.",
                "tugas": [
                    "Draft Rencana Kerja dan Anggaran (RKA)",
                    "Draft Key Performance Indicator (rencana kinerja) unit kerja/fungsi",
                    "Laporan pertanggungjawaban penggunaan anggaran unit kerja/fungsi."
                ]
            },
            {
                "id": 80,
                "header": "<b>Pengelolaan HSSE</b> Melaksanakan dan memonitor program-program budaya HSSE dan pengelolaan risiko HSSE berbasis sistem manajemen HSSE yang diimplementasikan oleh perusahaan.",
                "tugas": [
                    "Mengupayakan implementasi program budaya HSSE pada segala aspek kegiatan fungsi untuk mencapai level budaya generatif",
                    "Mengupayakan implementasi kebijakan perusahaan terkait aspek HSSE",
                    "Mengupayakan implementasi program pengelolaan risiko aspek HSSE yang terkait dengan kegiatan operasional fungsi",
                    "Mengupayakan parameter leading & lagging indicator aspek HSSE sebagai bagian yang tidak terpisahkan dari kinerja bisnis perusahaan."
                ]
            },
            {
                "id": 81,
                "header": "<b>Pembinaan Pekerja</b> Mengelola, mengevaluasi, dan memastikan kegiatan perencanaan dan penilaian kinerja pekerja, serta pembimbingan pekerja di unit kerja/fungsi, termasuk pada perilaku indisipliner pekerja;;Mengelola, mengevaluasi, dan memastikan kebutuhan pelatihan dan pengembangan pekerja di unit kerja/fungsi.",
                "tugas": [
                    "Usulan terkait dengan :",
                    "Rencana kebutuhan pekerja di unit/fungsi",
                    "Target dan ukuran kinerja pekerja",
                    "Laporan monitoring coaching-counseling",
                    "Rencana pengembangan individu (pelatihan dan penugasan)",
                    "Hasil penilaian kinerja pekerja."
                ]
            },
            {
                "id": 82,
                "header": "<b>Sistem Tata Kerja</b> Mengelola, mengevaluasi, dan memastikan penyusunan, sosialisasi dan memonitor pelaksanaan kebijakan, Sistem dan Tata Kerja (STK), di unit kerja/fungsi serta melakukan dan memonitor kegiatan transfer knowledge di unit kerja/fungsi.",
                "tugas": [
                    "Dokumen Sistem dan Tata Kerja (STK)",
                    "Implementasi dan evaluasi STK/TKO",
                    "Laporan kegiatan sharing dan transfer knowledge",
                    "Data aset pengetahuan yang termutakhir."
                ]
            },
            {
                "id": 83,
                "header": "<b>Pengelolaan Risiko & Kepatuhan GCG</b> Mengelola, mengevaluasi, dan memastikan pengelolaan risiko yang meliputi identifikasi, mitigasi, monitoring risiko, dan program budaya risiko, serta pengelolaan kepatuhan terhadap standar GCG di unit kerja/fungsi.",
                "tugas": [
                    "Hasil identifikasi risiko",
                    "Rencana dan realisasi mitigasi risiko",
                    "Dokumen terkait kepatuhan terhadap standar GCG",
                    "Mengupayakan implementasi program budaya risiko pada segala aspek kegiatan fungsi."
                ]
            },
            {
                "id": 84,
                "header": "<b>Tindak Lanjut Hasil Audit</b> Mengelola, mengevaluasi, dan memastikan pelaksanaan audit serta monitoring dan tindak lanjut hasil audit di unit kerja/fungsi.",
                "tugas": [
                    "Laporan implementasi tidak lanjut hasil audit",
                    "Kelengkapan data dan dokumen untuk proses audit."
                ]
            },
            {
                "id": 85,
                "header": "<b>Procurement </b> Mengelola, mengevaluasi, dan memastikan kegiatan pengadaan sesuai dengan kewenangan tertentu untuk kebutuhan unit kerja/fungsi.",
                "tugas": [
                    "Usulan rencana pengadaan",
                    "Dokumen terkait pengadaan barang/jasa",
                    "Tersedianya barang/jasa",
                    "Hasil perhitungan TKDN",
                    "Hasil penilaian kinerja penyedia barang/jasa",
                    "Terlaksananya penerimaan barang/jasa."
                ]
            },
            {
                "id": 86,
                "header": "<b>Project</b> Mengelola, mengevaluasi, dan memastikan pelaksanaan project dilakukan sesuai penugasan dan kewenangan yang diberikan untuk kebutuhan perusahaan.",
                "tugas": [
                    "Tersedianya sumber daya yang diperlukan untuk pelaksanaan project",
                    "Terlaksananya eksekusi project",
                    "Tersedianya hasil monitoring dan evaluasi pelaksanaan project."
                ]
            },
            {
                "id": 87,
                "header": "<b>Pengelolaan Data Insight</b> Mengelola, mengevaluasi, dan memastikan kegiatan pengelolaan, pengolahan, dan penyajian data.",
                "tugas": [
                    "Terlaksananya pengelolaan data",
                    "Tersedianya hasil pengolahan dan penyajian data."
                ]
            }
        ],
